/// @group Look
/// @desc Overall gain
/// @slider 0 4
/// @sort 5
uniform float Gain = 0.5;
/// @name Base Tint
/// @sort 32
uniform float4 Tint = float4(1.0, 0.5, 0.25, 1.0);
/// @sort 32
uniform Texture2D Source;
/// @static
/// @sort 32
uniform bool UseWarm = true;
// The four uniform shapes with metadata: group, description, slider, explicit sort, parameter name.
/// @name M_LpUniforms
export void M_LpUniforms(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    Color = Tint.rgb * Gain;
    Base.EmissiveColor = Color;
}
